import hashlib, os
root='dosyalar'
lines=[l.strip() for l in open('kopyalar.txt',encoding='utf-8') if l.strip()]
def sha(p): return hashlib.sha256(open(p,'rb').read()).hexdigest()
ok=True
for line in lines:
    paths=line.split(' | ')
    paths_s=sorted(paths)
    assert paths==paths_s, ('sıra hatalı',line)
    hs={sha(os.path.join(root,pp)) for pp in paths}
    assert len(hs)==1, ('içerik farkı',line)
    for pp in paths:
        assert os.path.exists(os.path.join(root,pp)), ('dosya yok',pp)
assert lines==sorted(lines,key=lambda l:l.split(' | ')[0]), ('satır sırası')
# hiçbir kopya grubu atlanmadı mı?
d={}
for dp,_,fns in os.walk(root):
    for fn in fns:
        p=os.path.join(dp,fn)
        d.setdefault(sha(p),set()).add(os.path.relpath(p,root).replace(os.sep,'/'))
expected=sorted(' | '.join(sorted(s)) for s in d.values() if len(s)>1)
assert expected==lines, ('eksik grup',expected,lines)
print('TAMAM: satır sayı',len(lines),'| içerik, sıra ve tamamlık doğrulandı')

